// National incidence must use people at risk, not the share of victims or case counts.
export const RISK_SOURCE={name:'한국형사·법무정책연구원 · 전국범죄피해조사 2022',year:2022,url:'https://www.kicj.re.kr/board.es?act=view&bid=0001&list_no=14021&mid=a10101000000'};
export function riskEvidence(s){const years=s.startAge+Math.floor(((Number(s.month.slice(0,4))*12+Number(s.month.slice(5)))-(Number(s.start.slice(0,4))*12+Number(s.start.slice(5))))/12);return {status:'unavailable',age:years,year:Number(s.month.slice(0,4)),annualProbability:null,monthlyProbability:null,source:RISK_SOURCE,message:`${years}세 · ${s.month.slice(0,4)}년의 이 사건 피해 확률은 자료 미연결입니다. 현재 등장 빈도는 게임 설정이며 한국인의 실제 피해 비율이 아닙니다.`};}
export function riskEvidenceHTML(s,e){const r=riskEvidence(s);return `<details class="risk-evidence"><summary>이 사건은 실제로 얼마나 발생할까요?</summary><p>${e(r.message)}</p><p>나이별 통계는 조사에 공개된 연령대로 표시합니다. 피해자 중 특정 나이의 비중을 그 나이의 피해 확률로 사용하지 않습니다. 연간 피해 비율과 월별 등장 확률도 구분합니다.</p><a href="${r.source.url}" target="_blank" rel="noopener noreferrer">${e(r.source.name)} · 통계 기준 확인 ↗</a></details>`;}
